'use strict';
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const web = path.resolve(__dirname, '../zmala_server/web');
const scripts = [
  'state',
  'shared',
  'auth',
  'setup',
  'clipboard',
  'accounts',
  'console',
  'groups',
  'ringtones',
  'terminalfields',
  'terminals',
  'callbacks',
  'backups',
  'pages',
  'main',
];
// Keep responsive rules last so component styles cannot undo narrow-screen layouts.
const styles = ['theme', 'tools', 'layout', 'pages', 'forms', 'terminals', 'responsive'];
const header =
  '/* Generated by build_tools/build-admin.cjs. Edit the source modules, then rebuild. */\n';

/** This small bundle supports only local named imports and exported functions/constants.
 * The source modules deliberately share unique top-level names. A single public script
 * and stylesheet also work with already-running servers and require no build dependency.
 */
function bundleScript() {
  const modules = scripts.map((name) => {
    let source = fs.readFileSync(path.join(web, `admin-${name}.js`), 'utf8');
    source = source.replace(/^import\s+\{[^}]*\}\s+from\s+['"]\.\/admin-[a-z]+\.js['"];\s*/gm, '');
    source = source.replace(/^export\s+(?=(?:async\s+)?function\b|const\b)/gm, '');
    if (/^\s*(?:import|export)\s/m.test(source))
      throw Error(`Unsupported module syntax in admin-${name}.js; update the admin build.`);
    return `// admin-${name}.js\n${source}`;
  });
  const output = header + "(() => {\n'use strict';\n" + modules.join('\n') + '\n})();\n';
  new vm.Script(output); // Catch name collisions and syntax errors before replacing the live asset.
  return output;
}

function buildAdmin(check = false) {
  const outputs = {
    'admin.js': bundleScript(),
    'admin.css':
      header +
      styles
        .map(
          (name) =>
            `/* styles/${name}.css */\n` +
            fs.readFileSync(path.join(web, 'styles', name + '.css'), 'utf8'),
        )
        .join('\n'),
  };
  for (const [name, contents] of Object.entries(outputs)) {
    const file = path.join(web, name);
    if (fs.existsSync(file) && fs.readFileSync(file, 'utf8') === contents) continue;
    if (check) throw Error(`${name} needs rebuilding: npm run build:admin`);
    const temporary = file + '.tmp';
    fs.writeFileSync(temporary, contents);
    fs.renameSync(temporary, file);
  }
}
if (require.main === module) buildAdmin(process.argv.includes('--check'));
module.exports = { buildAdmin };
